package io.github.jesterportfolio.hearth.economy;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class EconomyRuntimeSettingsTest {
    static Map<String,Object> settings(){var m=new HashMap<String,Object>();m.put("realm",UUID.randomUUID().toString());m.put("world-key","hearth_economy:trade");m.put("world-uuid",UUID.randomUUID().toString());m.put("entry-x",5.5);m.put("entry-y",64);m.put("entry-z",5.5);m.put("entry-yaw",0);m.put("entry-pitch",0);m.put("idle-seconds",30);m.put("required-regions",List.of("capital"));m.put("content-file","economy.properties");m.put("db-host","127.0.0.1");m.put("db-port",5432);m.put("db-name","hearth_economy");m.put("db-user","hearth");m.put("password-environment","HEARTH_DB_PASSWORD");return m;}
    @Test void explicitEconomyModeAndVerificationAreMutuallyExclusive(){assertEquals("disabled",EconomyRuntimeSettings.mode("disabled",false));assertEquals("disabled",EconomyRuntimeSettings.mode("disabled",true));assertEquals("economy",EconomyRuntimeSettings.mode("economy",false));assertEquals("story",EconomyRuntimeSettings.mode("story",false));assertEquals("story-prepare",EconomyRuntimeSettings.mode("story-prepare",false));assertThrows(IllegalArgumentException.class,()->EconomyRuntimeSettings.mode("economy",true));assertThrows(IllegalArgumentException.class,()->EconomyRuntimeSettings.mode("story",true));assertThrows(IllegalArgumentException.class,()->EconomyRuntimeSettings.mode("story-prepare",true));for(String bad:new String[]{null,"unknown",""})assertThrows(IllegalArgumentException.class,()->EconomyRuntimeSettings.mode(bad,false));}
    @Test void completeSettingsContainOnlyPasswordEnvironmentName(){var result=EconomyRuntimeSettings.parse(settings());assertEquals("HEARTH_DB_PASSWORD",result.passwordEnvironment());assertEquals(30,result.idleSeconds());assertEquals(Set.of("capital"),result.regions());assertThrows(UnsupportedOperationException.class,()->result.regions().add("other"));}
    @Test void missingRequiredSettingsAreNotReplacedWithTestWorldOrAccounts(){for(String key:settings().keySet()){var p=settings();p.remove(key);assertThrows(RuntimeException.class,()->EconomyRuntimeSettings.parse(p),key);}}
    @Test void pathTraversalPrimaryWorldInvalidIdentityAndEmptyProtectionRejected(){for(var change:List.of(Map.of("world-key","minecraft:overworld"),Map.of("world-key","hearth_economy:../world"),Map.of("world-uuid","bad"),Map.of("content-file","../private.properties"),Map.of("content-file","/absolute.properties"),Map.of("required-regions",List.of()),Map.of("required-regions",List.of("../bad")))){var p=settings();p.putAll(change);assertThrows(RuntimeException.class,()->EconomyRuntimeSettings.parse(p));}}
    @Test void unsafeCoordinatesAndFractionalOrOutOfBoundLimitsRejected(){for(var change:List.of(Map.of("entry-x",Double.NaN),Map.of("entry-y",Double.POSITIVE_INFINITY),Map.of("entry-pitch",91),Map.of("entry-x",30_000_000),Map.of("idle-seconds",0),Map.of("idle-seconds",3601),Map.of("idle-seconds",1.5),Map.of("db-port",0),Map.of("db-port",65536),Map.of("db-port",5432.5))){var p=settings();p.putAll(change);assertThrows(RuntimeException.class,()->EconomyRuntimeSettings.parse(p));}}
    @Test void connectionStringsCredentialsAndUnknownPasswordVariableAreNotConfigurationValues(){for(var change:List.of(Map.of("db-host","host/password"),Map.of("db-name","postgres;drop database"),Map.of("db-user","user@host"),Map.of("password-environment","secret=value"))){var p=settings();p.putAll(change);assertThrows(RuntimeException.class,()->EconomyRuntimeSettings.parse(p));}}
}
